import{_ as t,o as h,c as a,a3 as c}from"./chunks/framework.DX_KL3e0.js";const s=JSON.parse('{"title":"Người dùng cuối (User)","description":"","frontmatter":{},"headers":[],"relativePath":"vai-tro/nguoi-dung-cuoi.md","filePath":"vai-tro/nguoi-dung-cuoi.md","lastUpdated":1781595364000}'),i={name:"vai-tro/nguoi-dung-cuoi.md"};function o(g,n,e,r,u,d){return h(),a("div",null,[...n[0]||(n[0]=[c('<h1 id="nguoi-dung-cuoi-user" tabindex="-1">Người dùng cuối (User) <a class="header-anchor" href="#nguoi-dung-cuoi-user" aria-label="Permalink to &quot;Người dùng cuối (User)&quot;">​</a></h1><p>Trang <strong>lối đi nhanh</strong> dành cho vai trò <strong>Người dùng</strong> (<code>user</code>) — phần lớn nhân viên trong công ty. Vai trò này tập trung vào <strong>tự phục vụ</strong>: gửi yêu cầu, đặt phòng, chấm công và xem hồ sơ cá nhân.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Mã vai trò:</strong> <code>user</code>.</li><li><strong>Phạm vi dữ liệu:</strong> chỉ dữ liệu của <strong>chính bạn</strong>.</li><li><strong>Quyền mặc định:</strong> chỉ <code>Xem</code> ở những module có hành động <code>Xem</code>; ngoài ra có các module tự phục vụ luôn mở.</li></ul></div><h2 id="ban-thay-nhung-gi" tabindex="-1">Bạn thấy những gì? <a class="header-anchor" href="#ban-thay-nhung-gi" aria-label="Permalink to &quot;Bạn thấy những gì?&quot;">​</a></h2><p>Một số module <strong>luôn hiển thị</strong> với mọi người đã đăng nhập, kể cả khi chưa được cấp quyền chi tiết:</p><table tabindex="0"><thead><tr><th>Module</th><th>Đường dẫn</th><th>Dùng để</th></tr></thead><tbody><tr><td><strong>Tra Cứu</strong></td><td><code>/tra-cuu</code></td><td>Tra cứu tài sản, thông tin liên quan đến bạn.</td></tr><tr><td><strong>Dữ Liệu Chấm Công</strong></td><td><code>/tra-cuu/du-lieu-cong</code></td><td>Điểm danh, xem bảng công cá nhân.</td></tr><tr><td><strong>Hồ sơ của tôi</strong></td><td><code>/ho-so-cua-toi</code></td><td>Hợp đồng &amp; hồ sơ nhân sự của bạn.</td></tr></tbody></table><p>Ngoài ra, theo cấu hình mặc định bạn thường dùng được: <strong>Ticket Hỗ trợ</strong>, <strong>Đặt phòng họp</strong> và <strong>Cài đặt</strong> (cá nhân).</p><div class="tip custom-block"><p class="custom-block-title">Không thấy một mục nào đó?</p><p>Menu hiển thị theo phân quyền. Nếu thiếu mục bạn cần, hãy liên hệ Admin để được cấp quyền. Xem <a href="/help/bat-dau/phan-quyen.html">Phân quyền &amp; vai trò</a>.</p></div><h2 id="cong-viec-thuong-ngay" tabindex="-1">Công việc thường ngày <a class="header-anchor" href="#cong-viec-thuong-ngay" aria-label="Permalink to &quot;Công việc thường ngày&quot;">​</a></h2><ul><li>[ ] Gửi và theo dõi yêu cầu hỗ trợ → <a href="/help/chuc-nang/tickets.html">Ticket Hỗ trợ</a></li><li>[ ] Đặt phòng họp cho cuộc họp của bạn → <a href="/help/chuc-nang/dat-phong.html">Đặt phòng họp</a></li><li>[ ] Điểm danh vào/ra ca hằng ngày → <a href="/help/chuc-nang/cham-cong.html">Chấm công &amp; Nghỉ phép</a></li><li>[ ] Xem bảng công, kiểm tra ngày phép còn lại → <a href="/help/chuc-nang/cham-cong.html">Chấm công &amp; Nghỉ phép</a></li><li>[ ] Xem hợp đồng, hồ sơ và thông tin cá nhân → <a href="/help/chuc-nang/ho-so-cua-toi.html">Hồ sơ của tôi</a></li><li>[ ] Tra cứu tài sản đang được cấp cho bạn → <a href="/help/chuc-nang/tra-cuu.html">Tra cứu</a></li><li>[ ] Cập nhật thông tin cá nhân, đổi mật khẩu → <a href="/help/quan-tri/cai-dat.html">Cài đặt hệ thống</a></li></ul><div class="info custom-block"><p class="custom-block-title">📸 Ảnh minh họa</p><p>Giao diện chính khi đăng nhập bằng vai trò Người dùng. <em>(Ảnh sẽ được bổ sung.)</em></p></div><hr><p><em>Liên quan:</em> <a href="/help/bat-dau/phan-quyen.html">Phân quyền &amp; vai trò</a> · <a href="/help/bat-dau/giao-dien-chung.html">Giao diện chung</a></p>',13)])])}const p=t(i,[["render",o]]);export{s as __pageData,p as default};
